# Let me check: from orig 8s, can you reach 0s by going down/right only?
def reach_by_down_right(pos, grid):
    """Check if pos is reachable from any orig_8 by only going down/right through 0s"""
    from collections import deque
    r, c = pos
    # Check reverse: can we go up/left from pos to reach any orig_8?
    # That's the same as going down/right from orig_8 to pos
    queue = deque([(r, c)])
    visited = set([(r, c)])

    while queue:
        cur_r, cur_c = queue.popleft()
        for dr, dc in [(-1,0),(0,-1)]:  # Go up and left (reverse of down/right)
            nr, nc = cur_r+dr, cur_c+dc
            if 0 <= nr < 12 and 0 <= nc < 18:
                if (nr, nc) not in visited:
                    # Check if this cell has 0 in input (value=1 in our grid)
                    if grid[nr][nc] == 1:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
                    # If it has orig_8, we're done
                    if (nr, nc) in orig_8s:
                        return True
    return False

# Check reachable cells
